import React, {useEffect, useState} from 'react';
import {
	AbsoluteFill,
	continueRender,
	delayRender,
	Easing,
	interpolate,
	useCurrentFrame,
	useVideoConfig,
} from 'remotion';

/* ------------------------------------------------------------------ *
 *  AI IMAGE STUDIO — prompt typing into a diffusion reveal
 *  1920x1080 | 60fps | 15s
 *
 *  The reveal is a real denoise, not a cross-fade: the source is laid
 *  out at a tiny pixel size and scaled up with image-rendering:pixelated,
 *  so early frames are genuine coarse colour blocks that refine as the
 *  block grid subdivides. Blur, chroma noise and saturation ride the
 *  same curve, which is what a diffusion sampler actually looks like
 *  going from latent noise to a finished frame.
 *
 *  TO USE YOUR OWN PICTURE: replace the single IMG constant below with
 *  your own base64 data URI. Nothing else needs to change — the slot is
 *  1:1 and the artwork is object-fit: cover.
 * ------------------------------------------------------------------ */

const IMG = 'data:image/jpeg;base64,';

const FONT = 'InterStudio';
const F5 = '';
const F7 = '';
const F8 = '';
let fontRequested = false;
const ensureFont = () => {
	if (fontRequested || typeof document === 'undefined') return;
	fontRequested = true;
	const el = document.createElement('style');
	const face = (w: number, b: string) =>
		"@font-face{font-family:'" + FONT + "';font-style:normal;font-weight:" + w +
		';font-display:block;src:url(data:font/woff2;base64,' + b + ") format('woff2');}";
	el.textContent = face(500, F5) + face(700, F7) + face(800, F8);
	document.head.appendChild(el);
};

const W = 1920;
const H = 1080;
const TAU = Math.PI * 2;

/* palette — botanical dark, deliberately away from the reference violet */
const INK = '#EEF6EE';
const DIM = '#7E9585';
const DIM2 = '#4E6455';
const MINT = '#5FE0A8';
const AMBER = '#F5B44A';
const LINE = 'rgba(120,190,150,0.16)';
const LINE2 = 'rgba(120,190,150,0.3)';

/* card + slot geometry */
const CX0 = 210;
const CY0 = 168;
const CW = 1500;
const CH = 776;
const SLOT = 724;
const SX = CX0 + CW - 28 - SLOT;
const SY = CY0 + 26;
const LX = CX0 + 48;

const PROMPT =
	'A crescent moon above layered mountain ridges at dawn, sea of clouds filling the valley, warm golden horizon';

const EASE = Easing.bezier(0.16, 0.86, 0.22, 1);

let _s = 0x77c1a35b >>> 0;
const rr = () => {
	_s = (Math.imul(_s, 1664525) + 1013904223) >>> 0;
	return _s / 4294967296;
};
const ORB = Array.from({length: 7}, () => ({
	x: rr() * W,
	y: rr() * H,
	r: 200 + rr() * 420,
	c: rr() < 0.5 ? '90,220,150' : '235,170,70',
	o: 0.05 + rr() * 0.07,
	ax: 40 + rr() * 90,
	ay: 30 + rr() * 70,
	f1: 1 + Math.floor(rr() * 2),
	f2: 1 + Math.floor(rr() * 2),
	p1: rr(),
	p2: rr(),
}));

export const Motion: React.FC = () => {
	const frame = useCurrentFrame();
	const {fps, durationInFrames} = useVideoConfig();
	const t = frame / fps;
	const u = frame / durationInFrames;

	const [fh] = useState(() => delayRender('studio-font'));
	useEffect(() => {
		let done = false;
		const fin = () => {
			if (done) return;
			done = true;
			continueRender(fh);
		};
		ensureFont();
		const id = setTimeout(fin, 2500);
		Promise.all([
			document.fonts.load('500 16px ' + FONT),
			document.fonts.load('700 16px ' + FONT),
			document.fonts.load('800 44px ' + FONT),
		])
			.then(fin)
			.catch(fin);
		return () => clearTimeout(id);
	}, [fh]);

	const at = (s: number, d: number, e = EASE) =>
		interpolate(t, [s, s + d], [0, 1], {
			extrapolateLeft: 'clamp',
			extrapolateRight: 'clamp',
			easing: e,
		});

	/* ---------- beats ---------- */
	const intro = at(0, 0.6);
	const typeRaw = interpolate(t, [0.75, 4.8], [0, 1], {
		extrapolateLeft: 'clamp',
		extrapolateRight: 'clamp',
	});
	/* uneven keystrokes — bursts and hesitations, never backwards */
	const typed = Math.min(1, Math.max(0, typeRaw + 0.022 * Math.sin(TAU * typeRaw * 5)));
	const nChar = Math.round(PROMPT.length * typed);
	const shown = PROMPT.slice(0, nChar);

	const press = at(4.92, 0.12);
	const release = at(5.06, 0.16);
	const btnScale = 1 - 0.045 * press + 0.045 * release;
	const gen = interpolate(t, [5.25, 10.9], [0, 1], {
		extrapolateLeft: 'clamp',
		extrapolateRight: 'clamp',
		easing: Easing.bezier(0.3, 0.02, 0.2, 1),
	});
	const busy = t > 5.15 && gen < 1;
	const doneT = at(11.0, 0.5);
	/* nothing happens inside the slot until the button is actually pressed:
	   the latent bed and the denoise readout are both gated on this */
	const started = at(5.12, 0.18);
	const idleO = 1 - started;

	/* ---------- diffusion state ---------- */
	/* the block grid subdivides geometrically: 5 px -> full resolution */
	const res = Math.max(5, Math.round(5 * Math.pow(SLOT / 5, Math.pow(gen, 0.86))));
	const blurPx = interpolate(gen, [0, 0.55, 0.85, 1], [26, 9, 2.4, 0], {
		extrapolateRight: 'clamp',
	});
	const sat = interpolate(gen, [0, 0.4, 1], [0.25, 0.72, 1], {extrapolateRight: 'clamp'});
	const con = interpolate(gen, [0, 0.5, 1], [0.72, 0.92, 1], {extrapolateRight: 'clamp'});
	const noiseO = interpolate(gen, [0, 0.25, 0.7, 1], [0.72, 0.44, 0.12, 0], {
		extrapolateRight: 'clamp',
	});
	const imgO = interpolate(gen, [0, 0.07], [0, 1], {extrapolateRight: 'clamp'});
	/* sampler pass sweeping down the canvas */
	const passY = ((t - 5.25) * 0.62) % 1;
	const hold = at(11.2, 3.4);
	const kb = 1 + 0.02 * hold;

	const pct = Math.round(gen * 100);
	const steps = 4 + Math.round(gen * 24);

	const ctrl = (
		x: number,
		y: number,
		label: string,
		value: string,
		w: number,
		d: number
	) => {
		const a = at(0.34 + d, 0.5);
		return (
			<div
				style={{
					position: 'absolute',
					left: x,
					top: y,
					opacity: a,
					transform: 'translateY(' + ((1 - a) * 12).toFixed(1) + 'px)',
				}}
			>
				<div style={{fontSize: 12.5, fontWeight: 700, letterSpacing: 1.6, color: DIM2, marginBottom: 9}}>
					{label}
				</div>
				<div
					style={{
						width: w,
						height: 44,
						borderRadius: 10,
						border: '1px solid ' + LINE2,
						background: 'rgba(20,38,28,0.6)',
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'space-between',
						padding: '0 14px',
						boxSizing: 'border-box',
						fontSize: 14.5,
						fontWeight: 600,
						color: INK,
					}}
				>
					{value}
					<span style={{color: DIM2, fontSize: 11}}>&#9660;</span>
				</div>
			</div>
		);
	};

	return (
		<AbsoluteFill style={{backgroundColor: '#050B08', fontFamily: FONT}}>
			<AbsoluteFill
				style={{
					background:
						'radial-gradient(78% 86% at 46% 42%, #0E2419 0%, #091710 46%, #050B08 82%)',
				}}
			/>
			{ORB.map((o, i) => (
				<AbsoluteFill
					key={'o' + i}
					style={{
						background:
							'radial-gradient(' + o.r + 'px ' + o.r + 'px at ' +
							(o.x + o.ax * Math.sin(TAU * (u * o.f1 + o.p1))).toFixed(1) + 'px ' +
							(o.y + o.ay * Math.cos(TAU * (u * o.f2 + o.p2))).toFixed(1) +
							'px, rgba(' + o.c + ',' + o.o.toFixed(3) + ') 0%, rgba(' + o.c + ',0) 68%)',
					}}
				/>
			))}

			{/* ================= top navigation ================= */}
			<div style={{position: 'absolute', left: 64, top: 44, display: 'flex', alignItems: 'center', gap: 44, opacity: intro}}>
				<svg width={38} height={38} viewBox="0 0 38 38">
					<path d="M19 4 C10 10 6 17 6 23 a13 13 0 0 0 26 0 c0-6-4-13-13-19z" fill="none" stroke={MINT} strokeWidth={2} />
					<path d="M19 12 C14 16 12 20 12 23.5 a7 7 0 0 0 14 0 C26 20 24 16 19 12z" fill={MINT} opacity={0.3} />
				</svg>
				{['Generate', 'History', 'Presets', 'Pricing', 'Docs'].map((m, i) => (
					<span
						key={m}
						style={{fontSize: 15.5, fontWeight: i === 0 ? 700 : 500, color: i === 0 ? INK : DIM2, letterSpacing: 0.4}}
					>
						{m}
					</span>
				))}
			</div>
			<div
				style={{
					position: 'absolute',
					right: 64,
					top: 42,
					width: 42,
					height: 42,
					borderRadius: 21,
					border: '1px solid ' + LINE2,
					background: 'rgba(24,44,32,0.7)',
					opacity: intro,
					display: 'flex',
					alignItems: 'center',
					justifyContent: 'center',
				}}
			>
				<svg width={20} height={20} viewBox="0 0 20 20">
					<circle cx={10} cy={7} r={3.6} fill={DIM} />
					<path d="M3.5 17.5 C4.6 13.4 7 11.6 10 11.6 s5.4 1.8 6.5 5.9z" fill={DIM} />
				</svg>
			</div>

			{/* ================= card ================= */}
			<div
				style={{
					position: 'absolute',
					left: CX0,
					top: CY0,
					width: CW,
					height: CH,
					borderRadius: 26,
					border: '1px solid ' + LINE,
					background:
						'linear-gradient(150deg, rgba(20,44,32,0.72) 0%, rgba(10,24,17,0.78) 58%, rgba(6,15,11,0.82) 100%)',
					boxShadow: '0 40px 120px rgba(0,0,0,0.55)',
					opacity: intro,
					transform: 'translateY(' + ((1 - intro) * 26).toFixed(1) + 'px)',
				}}
			/>

			<div
				style={{
					position: 'absolute',
					left: LX,
					top: CY0 + 54,
					fontSize: 44,
					fontWeight: 800,
					letterSpacing: -0.4,
					color: INK,
					opacity: at(0.2, 0.5),
				}}
			>
				AI Image
			</div>

			{/* prompt box */}
			<div
				style={{
					position: 'absolute',
					left: LX,
					top: CY0 + 132,
					width: 610,
					height: 214,
					borderRadius: 14,
					border: '1px solid ' + (busy ? MINT + '66' : LINE2),
					background: 'rgba(16,32,23,0.66)',
					padding: '20px 22px',
					boxSizing: 'border-box',
					fontSize: 20,
					lineHeight: '32px',
					color: INK,
					opacity: at(0.28, 0.5),
					boxShadow: busy ? '0 0 26px rgba(95,224,168,0.14)' : 'none',
				}}
			>
				{shown}
				{typed < 1 ? (
					<span
						style={{
							display: 'inline-block',
							width: 2,
							height: 22,
							background: MINT,
							marginLeft: 2,
							transform: 'translateY(3px)',
							opacity: frame % 32 < 18 ? 1 : 0.15,
						}}
					/>
				) : null}
			</div>

			{ctrl(LX, CY0 + 382, 'ASPECT RATIO', '1 : 1', 190, 0.06)}
			{ctrl(LX + 214, CY0 + 382, 'SEED', '48192', 190, 0.1)}
			{ctrl(LX, CY0 + 480, 'STYLE', 'Photoreal', 190, 0.14)}
			{ctrl(LX + 214, CY0 + 480, 'QUALITY', 'Ultra', 190, 0.18)}

			{/* generate button */}
			<div
				style={{
					position: 'absolute',
					left: LX,
					top: CY0 + 596,
					width: 404,
					height: 62,
					opacity: at(0.44, 0.5),
					transform: 'scale(' + btnScale.toFixed(4) + ')',
					transformOrigin: '50% 50%',
				}}
			>
				<div
					style={{
						position: 'absolute',
						inset: -10,
						borderRadius: 22,
						background:
							'radial-gradient(60% 70% at 50% 50%, rgba(95,224,168,' + (0.16 + 0.16 * (busy ? 1 : 0) * (0.5 + 0.5 * Math.sin(t * 7))).toFixed(3) +
							'), rgba(95,224,168,0) 72%)',
						filter: 'blur(10px)',
					}}
				/>
				<div
					style={{
						position: 'absolute',
						inset: 0,
						borderRadius: 14,
						background: busy
							? 'linear-gradient(100deg, #1E5B44, #2C7A5C)'
							: 'linear-gradient(100deg, #4FD79E, #7DE9BE)',
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'center',
						gap: 12,
						color: busy ? '#BFF3DC' : '#05301F',
						fontSize: 17,
						fontWeight: 800,
						letterSpacing: 2.4,
					}}
				>
					{busy ? (
						<svg width={19} height={19} viewBox="0 0 19 19">
							<circle cx={9.5} cy={9.5} r={7} fill="none" stroke="#BFF3DC" strokeWidth={2.4} opacity={0.25} />
							<path
								d="M9.5 2.5 a7 7 0 0 1 7 7"
								fill="none"
								stroke="#BFF3DC"
								strokeWidth={2.4}
								strokeLinecap="round"
								transform={'rotate(' + ((t * 300) % 360).toFixed(1) + ' 9.5 9.5)'}
							/>
						</svg>
					) : null}
					{busy ? 'GENERATING' : gen >= 1 ? 'GENERATE AGAIN' : 'GENERATE'}
				</div>
			</div>

			{/* ================= image slot ================= */}
			<div
				style={{
					position: 'absolute',
					left: SX,
					top: SY,
					width: SLOT,
					height: SLOT,
					borderRadius: 18,
					overflow: 'hidden',
					background: '#08130D',
					border: '1px solid ' + LINE2,
					opacity: at(0.5, 0.5),
				}}
			>
				{/* empty slot, before Generate is pressed */}
				{idleO > 0.004 ? (
					<AbsoluteFill
						style={{
							opacity: idleO,
							display: 'flex',
							alignItems: 'center',
							justifyContent: 'center',
						}}
					>
						<div
							style={{
								position: 'absolute',
								left: 34,
								top: 34,
								right: 34,
								bottom: 34,
								borderRadius: 12,
								border: '1.5px dashed rgba(120,190,150,0.2)',
							}}
						/>
						<div
							style={{
								display: 'flex',
								flexDirection: 'column',
								alignItems: 'center',
								opacity: 0.86 + 0.14 * Math.sin(TAU * t * 0.3),
							}}
						>
							<svg width={96} height={96} viewBox="0 0 96 96">
								<rect x={8} y={16} width={80} height={64} rx={11} fill="none" stroke={DIM2} strokeWidth={2.4} />
								<circle cx={31} cy={37} r={7} fill={DIM2} opacity={0.6} />
								<path d="M13 74 L34 51 L49 64 L63 52 L83 74 Z" fill={DIM2} opacity={0.5} />
							</svg>
							<div style={{marginTop: 24, fontSize: 13, fontWeight: 700, letterSpacing: 2.6, color: DIM2}}>
								PREVIEW
							</div>
							<div style={{marginTop: 11, fontSize: 15, fontWeight: 500, letterSpacing: 0.3, color: 'rgba(126,149,133,0.62)'}}>
								Your generation will appear here
							</div>
						</div>
					</AbsoluteFill>
				) : null}

				{/* latent noise bed — only once sampling has actually begun */}
				<AbsoluteFill style={{opacity: started * Math.max(0, 1 - gen * 3.2)}}>
					<svg width={SLOT} height={SLOT}>
						<filter id="lat">
							<feTurbulence type="fractalNoise" baseFrequency="0.02" numOctaves={3} seed={(frame % 9) + 1} />
						</filter>
						<rect width={SLOT} height={SLOT} filter="url(#lat)" opacity={0.85} />
					</svg>
				</AbsoluteFill>

				{/* the picture, decoded at a coarse grid that subdivides */}
				<div
					style={{
						position: 'absolute',
						left: 0,
						top: 0,
						width: SLOT,
						height: SLOT,
						opacity: imgO,
						filter:
							'blur(' + blurPx.toFixed(2) + 'px) saturate(' + sat.toFixed(3) +
							') contrast(' + con.toFixed(3) + ')',
						transform: 'scale(' + kb.toFixed(4) + ')',
						transformOrigin: '50% 50%',
					}}
				>
					<img
						src={IMG}
						width={res}
						height={res}
						style={{
							width: res,
							height: res,
							objectFit: 'cover',
							imageRendering: 'pixelated',
							transform: 'scale(' + (SLOT / res).toFixed(4) + ')',
							transformOrigin: '0 0',
							display: 'block',
						}}
					/>
				</div>

				{/* chroma noise riding on top of the partial sample */}
				<AbsoluteFill style={{opacity: started * noiseO * 0.55, mixBlendMode: 'overlay', pointerEvents: 'none'}}>
					<svg width={SLOT} height={SLOT}>
						<filter id="dn">
							<feTurbulence type="fractalNoise" baseFrequency="0.55" numOctaves={2} seed={(frame % 11) + 1} />
						</filter>
						<rect width={SLOT} height={SLOT} filter="url(#dn)" />
					</svg>
				</AbsoluteFill>

				{/* sampler pass */}
				{busy ? (
					<div
						style={{
							position: 'absolute',
							left: 0,
							top: passY * SLOT - 60,
							width: SLOT,
							height: 120,
							background:
								'linear-gradient(180deg, rgba(95,224,168,0) 0%, rgba(95,224,168,0.16) 48%, rgba(180,255,220,0.5) 52%, rgba(95,224,168,0.14) 56%, rgba(95,224,168,0) 100%)',
							pointerEvents: 'none',
						}}
					/>
				) : null}

				{/* progress readout */}
				{busy ? (
					<div style={{position: 'absolute', left: 26, right: 26, bottom: 24}}>
						<div style={{display: 'flex', justifyContent: 'space-between', marginBottom: 10}}>
							<span style={{fontSize: 13, fontWeight: 700, letterSpacing: 2, color: '#CFF6E4'}}>
								DENOISING &#183; STEP {steps} / 28
							</span>
							<span style={{fontSize: 13, fontWeight: 800, letterSpacing: 1.2, color: '#CFF6E4', fontVariantNumeric: 'tabular-nums'}}>
								{pct}%
							</span>
						</div>
						<div style={{height: 4, borderRadius: 2, background: 'rgba(10,26,18,0.8)', overflow: 'hidden'}}>
							<div style={{width: pct + '%', height: '100%', background: 'linear-gradient(90deg,#3FBF8C,#8FF2CB)'}} />
						</div>
					</div>
				) : null}

				{/* done chip */}
				{doneT > 0.01 ? (
					<div
						style={{
							position: 'absolute',
							left: 24,
							top: 24,
							display: 'flex',
							alignItems: 'center',
							gap: 9,
							padding: '9px 15px 9px 12px',
							borderRadius: 10,
							background: 'rgba(8,26,18,0.72)',
							border: '1px solid rgba(95,224,168,0.42)',
							opacity: doneT,
							transform: 'translateY(' + ((1 - doneT) * -10).toFixed(1) + 'px)',
						}}
					>
						<svg width={15} height={15} viewBox="0 0 15 15">
							<path d="M2.5 8 L6 11.4 L12.5 3.6" fill="none" stroke={MINT} strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round" />
						</svg>
						<span style={{fontSize: 12.5, fontWeight: 700, letterSpacing: 1.6, color: '#CFF6E4'}}>
							1024 &#215; 1024 &#183; READY
						</span>
					</div>
				) : null}
			</div>

			{/* footer meta */}
			<div
				style={{
					position: 'absolute',
					left: LX,
					top: CY0 + CH - 44,
					fontSize: 12.5,
					fontWeight: 600,
					letterSpacing: 1.8,
					color: DIM2,
					opacity: at(0.6, 0.5),
				}}
			>
				MODEL v3.2 &#183; 28 STEPS &#183; CFG 7.5
			</div>

			{/* grade */}
			<AbsoluteFill
				style={{
					background:
						'radial-gradient(88% 90% at 50% 48%, rgba(0,0,0,0) 44%, rgba(4,10,7,0.45) 78%, rgba(2,6,4,0.9) 100%)',
					pointerEvents: 'none',
				}}
			/>
			<AbsoluteFill style={{opacity: 0.04, mixBlendMode: 'overlay', pointerEvents: 'none'}}>
				<svg width={W} height={H}>
					<filter id="grain43">
						<feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves={2} seed={(frame % 12) + 1} />
					</filter>
					<rect width={W} height={H} filter="url(#grain43)" />
				</svg>
			</AbsoluteFill>
		</AbsoluteFill>
	);
};

export default Motion;
